import{_ as n,a0 as d,w as o,s as p,ao as r,I as l,x as e,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 系統中通過用户組來管理用户 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系統中通過用户組來管理用户 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系統中通過用户組來管理用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系統中通過用户組來管理用户 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171201 How to Manage Users with Groups in Linux","title":"如何在 Linux 系統中通過用户組來管理用户","tag":"201712","desc":""},"relativePath":"201712/20171201 How to Manage Users with Groups in Linux.md","filePath":"[post].md"}'),h={name:"201712/20171201 How to Manage Users with Groups in Linux.md"};function c(u,s,g,k,b,m){const i=d("Link");return o(),p("div",null,[s[11]||(s[11]=r(`<h1 id="如何在-linux-系統中通過用户組來管理用户" tabindex="-1">如何在 Linux 系統中通過用户組來管理用户 <a class="header-anchor" href="#如何在-linux-系統中通過用户組來管理用户" aria-label="Permalink to “如何在 Linux 系統中通過用户組來管理用户”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/group-of-people-1645356_1920.jpg?itok=rJlAxBSV" alt="groups"></p><blockquote><p>本教程可以瞭解如何通過用户組和訪問控制表（ACL）來管理用户。</p></blockquote><p>當你需要管理一台容納多個用户的 Linux 機器時，比起一些基本的用户管理工具所提供的方法，有時候你需要對這些用户採取更多的用户權限管理方式。特別是當你要管理某些用户的權限時，這個想法尤為重要。比如説，你有一個目錄，某個用户組中的用户可以通過讀和寫的權限訪問這個目錄，而其他用户組中的用户對這個目錄只有讀的權限。在 Linux 中，這是完全可以實現的。但前提是你必須先了解如何通過用户組和訪問控制表（ACL）來管理用户。</p><p>我們將從簡單的用户開始，逐漸深入到複雜的訪問控制表（ACL）。你可以在你所選擇的 Linux 發行版完成你所需要做的一切。本文的重點是用户組，所以不會涉及到關於用户的基礎知識。</p><p>為了達到演示的目的，我將假設：</p><p>你需要用下面兩個用户名新建兩個用户：</p><ul><li>olivia</li><li>nathan</li></ul><p>你需要新建以下兩個用户組：</p><ul><li>readers</li><li>editors</li></ul><p>olivia 屬於 editors 用户組，而 nathan 屬於 readers 用户組。reader 用户組對 <code>/DATA</code> 目錄只有讀的權限，而 editors 用户組則對 <code>/DATA</code> 目錄同時有讀和寫的權限。當然，這是個非常小的任務，但它會給你基本的信息，你可以擴展這個任務以適應你其他更大的需求。</p><p>我將在 Ubuntu 16.04 Server 平台上進行演示。這些命令都是通用的，唯一不同的是，要是在你的發行版中不使用 <code>sudo</code> 命令，你必須切換到 root 用户來執行這些命令。</p><h3 id="創建用户" tabindex="-1">創建用户 <a class="header-anchor" href="#創建用户" aria-label="Permalink to “創建用户”">​</a></h3><p>我們需要做的第一件事是為我們的實驗創建兩個用户。可以用 <code>useradd</code> 命令來創建用户，我們不只是簡單地創建一個用户，而需要同時創建用户和屬於他們的家目錄，然後給他們設置密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo useradd -m olivia</span></span>
<span class="line"><span>sudo useradd -m nathan</span></span></code></pre></div><p>我們現在創建了兩個用户，如果你看看 <code>/home</code> 目錄，你可以發現他們的家目錄（因為我們用了 <code>-m</code> 選項，可以在創建用户的同時創建他們的家目錄。</p><p>之後，我們可以用以下命令給他們設置密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd olivia</span></span>
<span class="line"><span>sudo passwd nathan</span></span></code></pre></div><p>就這樣，我們創建了兩個用户。</p><h3 id="創建用户組並添加用户" tabindex="-1">創建用户組並添加用户 <a class="header-anchor" href="#創建用户組並添加用户" aria-label="Permalink to “創建用户組並添加用户”">​</a></h3><p>現在我們將創建 readers 和 editors 用户組，然後給它們添加用户。創建用户組的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>addgroup readers</span></span>
<span class="line"><span>addgroup editors</span></span></code></pre></div><p>（LCTT 譯註：當你使用 CentOS 等一些 Linux 發行版時，可能系統沒有 <code>addgroup</code> 這個命令，推薦使用 <code>groupadd</code> 命令來替換 <code>addgroup</code> 命令以達到同樣的效果）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/groups_1.jpg?itok=BKwL89BB" alt="groups"></p><p><em>圖一：我們可以使用剛創建的新用户組了。</em></p><p>創建用户組後，我們需要添加我們的用户到這兩個用户組。我們用以下命令來將 nathan 用户添加到 readers 用户組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G readers nathan</span></span></code></pre></div><p>用以下命令將 olivia 添加到 editors 用户組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G editors olivia</span></span></code></pre></div><p>現在我們可以通過用户組來管理用户了。</p><h3 id="給用户組授予目錄的權限" tabindex="-1">給用户組授予目錄的權限 <a class="header-anchor" href="#給用户組授予目錄的權限" aria-label="Permalink to “給用户組授予目錄的權限”">​</a></h3><p>假設你有個目錄 <code>/READERS</code> 且允許 readers 用户組的所有成員訪問這個目錄。首先，我們執行以下命令來更改目錄所屬用户組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chown -R :readers /READERS</span></span></code></pre></div><p>接下來，執行以下命令收回目錄所屬用户組的寫入權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod -R g-w /READERS</span></span></code></pre></div><p>然後我們執行下面的命令來收回其他用户對這個目錄的訪問權限（以防止任何不在 readers 組中的用户訪問這個目錄裏的文件）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod -R o-x /READERS</span></span></code></pre></div><p>這時候，只有目錄的所有者（root）和用户組 reader 中的用户可以訪問 <code>/READES</code> 中的文件。</p><p>假設你有個目錄 <code>/EDITORS</code> ，你需要給用户組 editors 裏的成員這個目錄的讀和寫的權限。為了達到這個目的，執行下面的這些命令是必要的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chown -R :editors /EDITORS</span></span>
<span class="line"><span>sudo chmod -R g+w /EDITORS</span></span>
<span class="line"><span>sudo chmod -R o-x /EDITORS</span></span></code></pre></div><p>此時 editors 用户組的所有成員都可以訪問和修改其中的文件。除此之外其他用户（除了 root 之外）無法訪問 <code>/EDITORS</code> 中的任何文件。</p><p>使用這個方法的問題在於，你一次只能操作一個組和一個目錄而已。這時候訪問控制表（ACL）就可以派得上用場了。</p><h3 id="使用訪問控制表-acl" tabindex="-1">使用訪問控制表（ACL） <a class="header-anchor" href="#使用訪問控制表-acl" aria-label="Permalink to “使用訪問控制表（ACL）”">​</a></h3><p>現在，讓我們把這個問題變得棘手一點。假設你有一個目錄 <code>/DATA</code> 並且你想給 readers 用户組的成員讀取權限，並同時給 editors 用户組的成員讀和寫的權限。為此，你必須要用到 <code>setfacl</code> 命令。<code>setfacl</code> 命令可以為文件或文件夾設置一個訪問控制表（ACL）。</p><p>這個命令的結構如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>setfacl OPTION X:NAME:Y /DIRECTORY</span></span></code></pre></div><p>其中 OPTION 是可選選項，X 可以是 <code>u</code>（用户）或者是 <code>g</code> （用户組），NAME 是用户或者用户組的名字，/DIRECTORY 是要用到的目錄。我們將使用 <code>-m</code> 選項進行修改。因此，我們給 readers 用户組添加讀取權限的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo setfacl -m g:readers:rx -R /DATA</span></span></code></pre></div><p>現在 readers 用户組裏面的每一個用户都可以讀取 <code>/DATA</code> 目錄裏的文件了，但是他們不能修改裏面的內容。</p><p>為了給 editors 用户組裏面的用户讀寫權限，我們執行了以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo setfacl -m g:editors:rwx -R /DATA</span></span></code></pre></div><p>上述命令將賦予 editors 用户組中的任何成員讀取權限，同時保留 readers 用户組的只讀權限。</p><h3 id="更多的權限控制" tabindex="-1">更多的權限控制 <a class="header-anchor" href="#更多的權限控制" aria-label="Permalink to “更多的權限控制”">​</a></h3><p>使用訪問控制表（ACL），你可以實現你所需的權限控制。你可以添加用户到用户組，並且靈活地控制這些用户組對每個目錄的權限以達到你的需求。如果想了解上述工具的更多信息，可以執行下列的命令：</p><ul><li><code>man usradd</code></li><li><code>man addgroup</code></li><li><code>man usermod</code></li><li><code>man sefacl</code></li><li><code>man chown</code></li><li><code>man chmod</code></li></ul><hr>`,56)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/12/how-manage-users-groups-linux"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.linux.com/learn/intro-to-linux/2017/12/how-manage-users-groups-linux",-1)])]),_:1})]),l("p",null,[s[4]||(s[4]=e("作者：[Jack Wallen] 譯者：",-1)),a(i,{href:"https://github.com/imquanquan"},{default:t(()=>[...s[2]||(s[2]=[e("imquanquan",-1)])]),_:1}),s[5]||(s[5]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[3]||(s[3]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[8]||(s[8]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[6]||(s[6]=[e("LCTT",-1)])]),_:1}),s[9]||(s[9]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[7]||(s[7]=[e("Linux中國",-1)])]),_:1}),s[10]||(s[10]=e(" 榮譽推出",-1))])])}const y=n(h,[["render",c]]);export{C as __pageData,y as default};
